actions.old_string:
specified_encoding: str | None = (
    any_specified_encoding(sequences) if preemptive_behaviour else None
)

if specified_encoding is not None:
    prioritized_encodings.append(specified_encoding)
    logger.log(
        TRACE,
        "Detected declarative mark in sequence. Priority +1 given for %s.",
        specified_encoding,
    )

actions.new_string:
# First check if content is valid UTF-8
try:
    sequences.decode('utf-8')
    is_utf8 = True
except UnicodeDecodeError:
    is_utf8 = False

specified_encoding: str | None = (
    any_specified_encoding(sequences) if preemptive_behaviour else None
)

if specified_encoding is not None and not (is_utf8 and specified_encoding != 'utf_8'):
    prioritized_encodings.append(specified_encoding)
    logger.log(
        TRACE,
        "Detected declarative mark in sequence. Priority +1 given for %s.",
        specified_encoding,
    )
